using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK discovers methods marked with [McpServerTool] and exposes them
/// to LLM clients. Parameters decorated with [Description] appear in the tool
/// schema so the model knows what to pass.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    /// <summary>
    /// HttpClient is constructor-injected by the DI container.  Because we
    /// register a named/typed client in Program.cs the base address and
    /// default headers are already configured.
    /// </summary>
    private readonly HttpClient _http;

    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location (e.g. 47.6062)")] double latitude,
        [Description("Longitude of the location (e.g. -122.3321)")] double longitude)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m,relative_humidity_2m";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var current = json.GetProperty("current");

        return JsonSerializer.Serialize(new
        {
            temperature_c = current.GetProperty("temperature_2m").GetDouble(),
            wind_speed_kmh = current.GetProperty("wind_speed_10m").GetDouble(),
            humidity_pct = current.GetProperty("relative_humidity_2m").GetDouble()
        }, JsonOptions);
    }

    [McpServerTool, Description("Get a 7-day daily temperature forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return JsonSerializer.Serialize(json.GetProperty("daily"), JsonOptions);
    }
}

